WITH filtered_returns AS ( SELECT cr.cr_net_loss, cr.cr_return_amount, cr.cr_return_quantity, cr.cr_order_number, cr.cr_reversed_charge, i.i_category, sm.sm_ship_mode_id, ca_refunded.ca_country, ca_returning.ca_state FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN time_dim t ON cr.cr_returned_time_sk = t.t_time_sk JOIN customer_address ca_refunded ON cr.cr_refunded_addr_sk = ca_refunded.ca_address_sk JOIN customer_address ca_returning ON cr.cr_returning_addr_sk = ca_returning.ca_address_sk WHERE cr.cr_reversed_charge > 100 AND t.t_hour BETWEEN 9 AND 17 AND i.i_category IS NOT NULL ) SELECT ca_country, ca_state, i_category, sm_ship_mode_id, SUM(cr_net_loss) AS total_net_loss, SUM(cr_return_amount) AS total_return_amount, AVG(cr_return_quantity) AS avg_return_qty, COUNT(DISTINCT cr_order_number) AS distinct_orders, RANK() OVER (PARTITION BY ca_country ORDER BY SUM(cr_net_loss) DESC) AS category_rank FROM filtered_returns GROUP BY ca_country, ca_state, i_category, sm_ship_mode_id ORDER BY ca_country, category_rank
